package com.alsafa.native4.core;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import com.alsafa.native4.sync.SyncOperation;import org.json.JSONObject;import java.util.UUID;import java.util.List;import java.util.ArrayList;
/** Repair workflow: partial payment stays due; explicit final price edit is an audited discount/increase. */
public final class RepairWorkflowStore {private final CoreStore.DbProvider provider;private final String deviceId;public RepairWorkflowStore(CoreStore.DbProvider provider,String deviceId){this.provider=provider;this.deviceId=deviceId;}
 public String receive(String customer,String phone,String watch,double total,String currency,String payment)throws Exception{String c=trim(customer),w=req(watch,"وصف الساعة"),cur=MoneyRules.currency(currency),pay=payment(payment);MoneyRules.requirePaymentSupported(pay,cur);if(total<0||!Double.isFinite(total))throw new IllegalArgumentException("المبلغ غير صالح");long now=System.currentTimeMillis();String id="repair-"+UUID.randomUUID(),no="R-"+now;SQLiteDatabase db=provider.db();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("repair_id",id);v.put("invoice_no",no);v.put("customer_name",c);v.put("customer_phone",trim(phone));v.put("watch_description",w);v.put("status","RECEIVED");v.put("total",total);v.put("currency",cur);v.put("payment_method",pay);v.put("received_at",now);v.put("updated_at",now);db.insertOrThrow("repairs",null,v);FxSnapshotStore.Snapshot fx=FxSnapshotStore.capture(db,"REPAIR",id,cur,total,now);enqueue(db,id,no,c,phone,w,"RECEIVED",total,cur,pay,fx,now);db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}
 public static final class PartRequest{public final String partId;public final int quantity;public PartRequest(String p,int q){partId=p;quantity=q;}}
 public String receiveWithParts(String customer,String phone,String watch,double total,String currency,String payment,List<PartRequest> parts)throws Exception{if(parts==null||parts.isEmpty())return receive(customer,phone,watch,total,currency,payment);String c=trim(customer),w=req(watch,"وصف الساعة"),cur=MoneyRules.currency(currency),pay=payment(payment);MoneyRules.requirePaymentSupported(pay,cur);if(total<0||!Double.isFinite(total))throw new IllegalArgumentException("المبلغ غير صالح");long now=System.currentTimeMillis();String id="repair-"+UUID.randomUUID(),no="R-"+now;SQLiteDatabase db=provider.db();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("repair_id",id);v.put("invoice_no",no);v.put("customer_name",c);v.put("customer_phone",trim(phone));v.put("watch_description",w);v.put("status","RECEIVED");v.put("total",total);v.put("currency",cur);v.put("payment_method",pay);v.put("received_at",now);v.put("updated_at",now);db.insertOrThrow("repairs",null,v);for(PartRequest pr:parts){String pid=req(pr.partId,"قطعة الصيانة");if(pr.quantity<=0)throw new IllegalArgumentException("كمية قطعة الصيانة غير صالحة");String pn;double cost;int before;try(Cursor pc=db.rawQuery("SELECT name,unit_cost,quantity FROM repair_inventory WHERE part_id=? AND deleted_at IS NULL",new String[]{pid})){if(!pc.moveToFirst())throw new IllegalArgumentException("قطعة الصيانة غير موجودة");pn=pc.getString(0);cost=pc.getDouble(1);before=pc.getInt(2);}if(before<pr.quantity)throw new IllegalArgumentException("رصيد قطعة الصيانة غير كافٍ: "+pn);int after=before-pr.quantity;ContentValues pv=new ContentValues();pv.put("quantity",after);pv.put("updated_at",now);db.update("repair_inventory",pv,"part_id=?",new String[]{pid});String item="repairpart-"+UUID.randomUUID();ContentValues iv=new ContentValues();iv.put("item_id",item);iv.put("repair_id",id);iv.put("part_id",pid);iv.put("description",pn);iv.put("quantity",pr.quantity);iv.put("unit_cost",cost);iv.put("created_at",now);db.insertOrThrow("repair_parts",null,iv);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.REPAIR,id,new JSONObject().put("repairId",id).put("partId",pid).put("quantity",pr.quantity).put("stockAfter",after).put("unitCost",cost).put("updatedAt",now).toString(),deviceId));}FxSnapshotStore.Snapshot fx=FxSnapshotStore.capture(db,"REPAIR",id,cur,total,now);enqueue(db,id,no,c,phone,w,"RECEIVED",total,cur,pay,fx,now);db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}
 public String receiveWithPart(String customer,String phone,String watch,double total,String currency,String payment,String partId,int qty)throws Exception{String c=trim(customer),w=req(watch,"وصف الساعة"),cur=MoneyRules.currency(currency),pay=payment(payment),pid=req(partId,"قطعة الصيانة");MoneyRules.requirePaymentSupported(pay,cur);if(total<0||!Double.isFinite(total)||qty<=0)throw new IllegalArgumentException("المبلغ أو كمية القطعة غير صالحة");long now=System.currentTimeMillis();String id="repair-"+UUID.randomUUID(),no="R-"+now;SQLiteDatabase db=provider.db();db.beginTransaction();try{String partName;double cost;int before;try(Cursor pc=db.rawQuery("SELECT name,unit_cost,quantity FROM repair_inventory WHERE part_id=? AND deleted_at IS NULL",new String[]{pid})){if(!pc.moveToFirst())throw new IllegalArgumentException("قطعة الصيانة غير موجودة");partName=pc.getString(0);cost=pc.getDouble(1);before=pc.getInt(2);}if(before<qty)throw new IllegalArgumentException("رصيد قطعة الصيانة غير كافٍ");ContentValues v=new ContentValues();v.put("repair_id",id);v.put("invoice_no",no);v.put("customer_name",c);v.put("customer_phone",trim(phone));v.put("watch_description",w);v.put("status","RECEIVED");v.put("total",total);v.put("currency",cur);v.put("payment_method",pay);v.put("received_at",now);v.put("updated_at",now);db.insertOrThrow("repairs",null,v);int after=before-qty;ContentValues pv=new ContentValues();pv.put("quantity",after);pv.put("updated_at",now);db.update("repair_inventory",pv,"part_id=?",new String[]{pid});String item="repairpart-"+UUID.randomUUID();ContentValues iv=new ContentValues();iv.put("item_id",item);iv.put("repair_id",id);iv.put("part_id",pid);iv.put("description",partName);iv.put("quantity",qty);iv.put("unit_cost",cost);iv.put("created_at",now);db.insertOrThrow("repair_parts",null,iv);FxSnapshotStore.Snapshot fx=FxSnapshotStore.capture(db,"REPAIR",id,cur,total,now);enqueue(db,id,no,c,phone,w,"RECEIVED",total,cur,pay,fx,now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.REPAIR,id,new JSONObject().put("repairId",id).put("partId",pid).put("quantity",qty).put("stockAfter",after).put("unitCost",cost).put("updatedAt",now).toString(),deviceId));db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}
 public Settlement collect(String repairId,double collected,String paymentMethod,String account,boolean finalPriceEdit,boolean confirmed,String reason)throws Exception{SQLiteDatabase db=provider.db();db.beginTransaction();try{double agreed;String cur;try(Cursor c=db.rawQuery("SELECT total,currency FROM repairs WHERE repair_id=? AND deleted_at IS NULL",new String[]{repairId})){if(!c.moveToFirst())throw new IllegalArgumentException("الصيانة غير موجودة");agreed=c.getDouble(0);cur=c.getString(1);}if(!Double.isFinite(collected)||collected<0)throw new IllegalArgumentException("المبلغ المحصل غير صالح");String pay=payment(paymentMethod),acc=req(account,"الخزنة").toUpperCase();MoneyRules.requireSupported(acc,cur);MoneyRules.requirePaymentSupported(pay,cur);long now=System.currentTimeMillis();double finalTotal=agreed,balance=Math.max(0,agreed-collected);SettlementAdjustmentStore.Result adj=null;if(finalPriceEdit&&Math.abs(collected-agreed)>0.000001){adj=SettlementAdjustmentStore.requireAndWrite(db,"REPAIR",repairId,agreed,collected,cur,confirmed,reason,now);finalTotal=collected;balance=0;ContentValues u=new ContentValues();u.put("total",finalTotal);u.put("updated_at",now);db.update("repairs",u,"repair_id=?",new String[]{repairId});}if(collected>0){java.util.List<SplitPaymentStore.Payment> ps=new java.util.ArrayList<>();ps.add(new SplitPaymentStore.Payment(collected,cur,pay,acc));SplitPaymentStore.write(db,"REPAIR",repairId,ps,now);}double difference=adj==null?0:adj.difference,discount=adj==null?0:adj.discount;String adjustmentKind=adj==null?"NONE":adj.kind;JSONObject j=new JSONObject().put("repairId",repairId).put("agreedAmount",agreed).put("collectedAmount",collected).put("finalAmount",finalTotal).put("currency",cur).put("finalPriceEdit",finalPriceEdit).put("adjustmentKind",adjustmentKind).put("customerDiscount",discount).put("adjustment",difference).put("balanceDue",balance).put("paymentMethod",pay).put("account",acc).put("updatedAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.REPAIR,repairId,j.toString(),deviceId));db.setTransactionSuccessful();return new Settlement(agreed,collected,finalTotal,balance,difference,discount,adjustmentKind,cur);}finally{db.endTransaction();}}
 public java.util.List<OpenRepair> openRepairs(){java.util.ArrayList<OpenRepair> out=new java.util.ArrayList<>();SQLiteDatabase db=provider.db();try(Cursor c=db.rawQuery("SELECT repair_id,invoice_no,customer_name,customer_phone,watch_description,status,total,currency,updated_at FROM repairs WHERE deleted_at IS NULL AND status<>? ORDER BY updated_at DESC LIMIT 200",new String[]{"DELIVERED"})){while(c.moveToNext())out.add(new OpenRepair(c.getString(0),c.getString(1),c.getString(2),c.getString(3),c.getString(4),c.getString(5),c.getDouble(6),c.getString(7),c.getLong(8)));}return out;}
 public static final class OpenRepair{public final String repairId,invoiceNo,customer,phone,watch,status,currency;public final double total;public final long updatedAt;OpenRepair(String id,String no,String customer,String phone,String watch,String status,double total,String currency,long updatedAt){this.repairId=id;this.invoiceNo=no;this.customer=customer;this.phone=phone;this.watch=watch;this.status=status;this.total=total;this.currency=currency;this.updatedAt=updatedAt;}}
 public void setStatus(String id,String status)throws Exception{String s=trim(status).toUpperCase();if(!s.equals("RECEIVED")&&!s.equals("IN_PROGRESS")&&!s.equals("READY")&&!s.equals("DELIVERED"))throw new IllegalArgumentException("حالة الصيانة غير صالحة");long now=System.currentTimeMillis();SQLiteDatabase db=provider.db();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("status",s);v.put("updated_at",now);if(s.equals("DELIVERED"))v.put("delivered_at",now);if(db.update("repairs",v,"repair_id=? AND deleted_at IS NULL",new String[]{id})!=1)throw new IllegalArgumentException("الصيانة غير موجودة");provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.REPAIR,id,new JSONObject().put("repairId",id).put("status",s).put("updatedAt",now).toString(),deviceId));db.setTransactionSuccessful();}finally{db.endTransaction();}}
 public int addPart(String repairId,String partId,int qty)throws Exception{if(qty<=0)throw new IllegalArgumentException("الكمية غير صالحة");SQLiteDatabase db=provider.db();db.beginTransaction();try{String name;double cost;int before;try(Cursor c=db.rawQuery("SELECT name,unit_cost,quantity FROM repair_inventory WHERE part_id=? AND deleted_at IS NULL",new String[]{partId})){if(!c.moveToFirst())throw new IllegalArgumentException("قطعة الصيانة غير موجودة");name=c.getString(0);cost=c.getDouble(1);before=c.getInt(2);}if(before<qty)throw new IllegalArgumentException("رصيد قطعة الصيانة غير كافٍ");long now=System.currentTimeMillis();int after=before-qty;ContentValues pv=new ContentValues();pv.put("quantity",after);pv.put("updated_at",now);db.update("repair_inventory",pv,"part_id=?",new String[]{partId});String item="repairpart-"+UUID.randomUUID();ContentValues iv=new ContentValues();iv.put("item_id",item);iv.put("repair_id",repairId);iv.put("part_id",partId);iv.put("description",name);iv.put("quantity",qty);iv.put("unit_cost",cost);iv.put("created_at",now);db.insertOrThrow("repair_parts",null,iv);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.REPAIR,repairId,new JSONObject().put("repairId",repairId).put("partId",partId).put("quantity",qty).put("stockAfter",after).put("unitCost",cost).put("updatedAt",now).toString(),deviceId));db.setTransactionSuccessful();return after;}finally{db.endTransaction();}}
 public String quick(String title,double price,String currency,String payment)throws Exception{return receive("","",req(title,"نوع الصيانة"),price,currency,payment);}
 private void enqueue(SQLiteDatabase db,String id,String no,String customer,String phone,String watch,String status,double total,String currency,String payment,FxSnapshotStore.Snapshot fx,long now)throws Exception{provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.REPAIR,id,new JSONObject().put("repairId",id).put("invoiceNo",no).put("customerName",customer).put("customerPhone",trim(phone)).put("watchDescription",watch).put("status",status).put("total",total).put("currency",currency).put("paymentMethod",payment).put("fxUsdPerUnit",fx.usdPerUnit).put("totalUsdSnapshot",fx.usdAmount).put("fxCapturedAt",fx.capturedAt).put("updatedAt",now).toString(),deviceId));}
 public static final class Settlement{public final double agreed,collected,finalTotal,balanceDue,adjustment,customerDiscount;public final String adjustmentKind,currency;Settlement(double a,double c,double f,double b,double d,double disc,String k,String cur){agreed=a;collected=c;finalTotal=f;balanceDue=b;adjustment=d;customerDiscount=disc;adjustmentKind=k;currency=cur;}}
 private static String payment(String v){String x=trim(v).toUpperCase();return x.equals("SHAM_CASH")||x.equals("BANK")||x.equals("EXTERNAL")||x.equals("LATER")?x:"CASH";}private static String req(String v,String label){String s=trim(v);if(s.isEmpty())throw new IllegalArgumentException(label+" مطلوب");return s;}private static String trim(String v){return v==null?"":v.trim();}}
